     "rif": "INAIL, Relazione annuale 2025 (settembre 2026)",
     "nar": "Si considerino i dati del 2025 nella prospettiva di chi assume le decisioni: circa seicentomila denunce di infortunio e 1.198 casi mortali. Quasi un infortunio su quattro avviene al di fuori dell’azienda, nel tragitto o alla guida di mezzi di trasporto. Le malattie professionali superano le novantottomila denunce, in forte crescita, e tre su quattro interessano l’apparato muscolo-scheletrico. L’Abruzzo è la terza regione per denunce di malattia professionale. Le priorità aziendali, tuttavia, si definiscono sulla base dei propri indicatori, confrontati nel tempo.",
