     "nar": "I dati infortunistici sono indispensabili, ma descrivono ciò che è già accaduto. Gli indicatori reattivi comprendono il numero di infortuni, le giornate perse, le malattie professionali denunciate e gli indici della norma UNI settemiladuecentoquarantanove: l’indice di frequenza, pari al numero di infortuni moltiplicato per un milione e diviso per le ore lavorate, e l’indice di gravità, pari alle giornate perse moltiplicate per mille e divise per le ore lavorate. Nelle piccole realtà questi numeri sono troppo bassi per indicare tendenze affidabili. Per questo chi dirige affianca indicatori proattivi, che misurano le attività di prevenzione: il numero di segnalazioni di quasi incidenti e di condizioni pericolose, i sopralluoghi svolti dai preposti, la percentuale di azioni correttive chiuse nei tempi stabiliti, la formazione erogata rispetto al piano, gli esiti delle verifiche periodiche e degli audit. La norma ISO quarantacinquemilauno chiede di fissare obiettivi misurabili, assegnare responsabilità e risorse e monitorarne il raggiungimento. Un aumento delle segnalazioni di quasi incidenti, in genere, non indica un peggioramento: segnala che i lavoratori hanno fiducia nel sistema. La riunione periodica è il momento naturale per discutere questi indicatori e riesaminare gli obiettivi.",
