     "nar": "La legge duecentoquindici del duemilaventuno ha rafforzato la figura del preposto. L’articolo diciotto, alla lettera b bis, impone oggi al datore di lavoro e ai dirigenti di individuare il preposto o i preposti per l’effettuazione delle attività di vigilanza dell’articolo diciannove. I contratti e gli accordi collettivi di lavoro possono stabilire l’emolumento spettante al preposto, che non può subire pregiudizio alcuno a causa dello svolgimento della propria attività. L’articolo diciannove ne ha ampliato i compiti: il preposto sovrintende e vigila sull’osservanza degli obblighi di legge e delle disposizioni aziendali; in caso di comportamenti non conformi interviene per modificarli fornendo le necessarie indicazioni di sicurezza e, se la mancata attuazione persiste o in caso di deficienze dei mezzi e delle attrezzature, interrompe temporaneamente l’attività e segnala tempestivamente le non conformità rilevate. La formazione del preposto, secondo l’Accordo Stato Regioni del duemilaventicinque, è di dodici ore, con un aggiornamento biennale di sei ore. Va ricordato che, in base all’articolo duecentonovantanove, chi esercita in concreto i poteri del preposto ne assume la posizione di garanzia anche senza nomina formale: l’individuazione esplicita serve proprio a chiarire compiti, ambiti e confini.",
