     "nar": "L’inserimento dei lavoratori con disabilità si fonda sulla valutazione individuale e sugli accomodamenti ragionevoli. Il datore di lavoro deve adottare le modifiche organizzative e materiali necessarie, salvo oneri sproporzionati. Il piano di emergenza deve prevedere l’evacuazione assistita, e il medico competente può indicare prescrizioni o limitazioni. L’obiettivo è adattare il lavoro alla persona.",
