     "appro": "Prima di dichiarare impossibile la ricollocazione di un lavoratore divenuto inidoneo, la giurisprudenza richiede di dimostrare di aver valutato gli accomodamenti possibili.",
     "rif": "D.lgs. 9 luglio 2003, n. 216, art. 3 c. 3-bis · Convenzione ONU sui diritti delle persone con disabilità · D.lgs. 81/2008, art. 42",
     "nar": "La tutela delle persone con disabilità nel lavoro non si esaurisce nel collocamento obbligatorio. L’articolo tre, comma tre bis, del decreto legislativo duecentosedici del duemilatré, che recepisce la direttiva europea sulla parità di trattamento, impone a tutti i datori di lavoro, pubblici e privati, di adottare accomodamenti ragionevoli nei luoghi di lavoro, per garantire alle persone con disabilità la piena eguaglianza con gli altri lavoratori. Un accomodamento è una modifica o un adattamento necessario e appropriato: può riguardare l’ambiente fisico, come una postazione regolabile o un accesso senza barriere, le attrezzature e gli ausili, i tempi di lavoro, come orari flessibili e pause, oppure l’organizzazione, come la redistribuzione di alcuni compiti. Il limite è che la misura non comporti un onere sproporzionato per il datore di lavoro. L’obbligo si coordina con il giudizio di idoneità del medico competente: le limitazioni e le prescrizioni indicano le condizioni a cui la prestazione è possibile. La giurisprudenza ha chiarito che, prima di dichiarare impossibile la ricollocazione di un lavoratore divenuto inidoneo, il datore di lavoro deve dimostrare di aver valutato gli accomodamenti ragionevoli praticabili. Il rifiuto ingiustificato costituisce una discriminazione.",
