     "nar": "Le riforme recenti hanno inciso profondamente sugli obblighi del datore di lavoro. La legge duecentoquindici del duemilaventuno ha reso obbligatoria l'individuazione dei preposti e rafforzato la vigilanza. Il decreto legge diciannove del duemilaventiquattro ha introdotto la patente a crediti nei cantieri, poi rafforzata dal decreto centocinquantanove del duemilaventicinque, che ha anche introdotto il badge di cantiere. Il decreto duecentotredici del duemilaventicinque ha ridotto il limite di esposizione all'amianto. L'Accordo del duemilaventicinque ha riordinato tutta la formazione.",
