      "Sospensione dell’attività (art. 14): quando almeno il 10% dei lavoratori presenti risulta occupato senza preventiva comunicazione di instaurazione del rapporto, oppure per gravi violazioni elencate nell’Allegato I",
      "Revoca della sospensione: regolarizzazione dei lavoratori, ripristino delle condizioni di sicurezza, pagamento della somma aggiuntiva",
