     "appro": "L’Allegato I individua violazioni gravi come la mancata elaborazione del DVR, la mancata formazione e addestramento, la mancata costituzione del servizio di prevenzione, la mancanza di protezioni contro le cadute dall’alto, i lavori in prossimità di linee elettriche senza precauzioni, la mancanza di protezioni sulle parti in movimento delle macchine. La sospensione è un provvedimento cautelare e amministrativo, distinto dalle sanzioni penali.",
     "rif": "Artt. 13, 14 e Allegato I D.lgs. 81/2008 · L. 215/2021",
     "nar": "La vigilanza è svolta dalle ASL, dall’Ispettorato Nazionale del Lavoro e, per l’antincendio, dai Vigili del fuoco. Gli ispettori sono ufficiali di polizia giudiziaria: possono accedere ai luoghi, esaminare documenti, campionare e disporre sequestri. L’attività può essere sospesa quando almeno il dieci per cento dei lavoratori presenti è irregolare o per gravi violazioni di sicurezza, come la mancanza del DVR o della formazione. La sospensione si revoca regolarizzando e ripristinando le condizioni di sicurezza.",
