     "appro": "La qualificazione dei tecnici manutentori si consegue con un percorso formativo e un esame davanti ai Vigili del fuoco.",
     "rif": "D.M. 1 settembre 2021 · D.M. 2 settembre 2021 · UNI 9994-1",
     "nar": "Il decreto ministeriale del primo settembre duemilaventuno, in vigore dal venticinque settembre duemilaventidue, disciplina i controlli e la manutenzione degli impianti, delle attrezzature e degli altri sistemi di sicurezza antincendio. Prevede tre livelli di attività. La sorveglianza è un controllo visivo periodico, svolto da personale interno adeguatamente formato, per verificare che estintori, idranti, porte tagliafuoco e illuminazione di sicurezza siano presenti, accessibili e senza danni evidenti. Il controllo periodico e la manutenzione si eseguono con la frequenza indicata dalle norme tecniche, dalle istruzioni del fabbricante e dalla regola dell’arte: per gli estintori portatili, ad esempio, la norma UNI novemilanovecentonovantaquattro prevede un controllo semestrale, oltre a revisioni e collaudi periodici. Gli interventi di manutenzione e controllo sono affidati a tecnici manutentori qualificati, che conseguono la qualificazione con un percorso formativo e un esame svolto presso i Vigili del fuoco, secondo l’Allegato secondo del decreto. Gli esiti si annotano nel registro dei controlli, da tenere aggiornato e a disposizione degli organi di vigilanza. Il datore di lavoro deve quindi verificare che il contratto di manutenzione preveda tecnici qualificati e che il registro sia completo.",
     "est": true,
     "ancora": "Gli addetti antincendio: il D.M. 2 settembre 2021"
