     "nar": "Il decreto ministeriale trecentottantotto del duemilatré classifica le aziende in tre gruppi, A, B e C, e stabilisce le attrezzature minime di primo soccorso. Nelle aziende dei gruppi A e B deve essere presente la cassetta di pronto soccorso, custodita in un luogo facilmente accessibile e segnalata con l’apposito cartello verde. Il suo contenuto minimo, indicato nell’Allegato uno, comprende tra l’altro guanti sterili monouso, una visiera paraschizzi, soluzione cutanea disinfettante e soluzione fisiologica, compresse di garza sterile di diverse misure, teli sterili, pinzette, cotone idrofilo, cerotti, forbici, lacci emostatici, confezioni di ghiaccio istantaneo, sacchetti per i rifiuti sanitari, un termometro e un apparecchio per la misurazione della pressione arteriosa. Nelle aziende del gruppo C basta il pacchetto di medicazione dell’Allegato due, con un contenuto ridotto. In ogni caso deve essere disponibile un mezzo di comunicazione idoneo ad attivare rapidamente il sistema di emergenza del servizio sanitario nazionale. Il contenuto minimo va integrato sulla base dei rischi specifici, su indicazione del medico competente. La cassetta si controlla periodicamente, verificando completezza e scadenze, e si reintegra subito dopo ogni utilizzo.",
