     "nar": "Il documento di valutazione dei rischi deve avere data certa, oppure essere attestata dalla sottoscrizione del datore di lavoro, del responsabile del servizio di prevenzione e protezione, del rappresentante dei lavoratori per la sicurezza e del medico competente, ove nominato. Non è un documento statico. L’articolo ventinove impone di rielaborare la valutazione in occasione di modifiche del processo produttivo o dell’organizzazione significative per la sicurezza, in relazione all’evoluzione della tecnica, a seguito di infortuni significativi o quando i risultati della sorveglianza sanitaria ne evidenziano la necessità. Le misure di prevenzione vanno aggiornate subito, e il documento rielaborato entro trenta giorni dalle rispettive cause. Per una nuova impresa il datore di lavoro effettua immediatamente la valutazione ed elabora il documento entro novanta giorni dall’inizio dell’attività, dimostrando comunque di aver adempiuto agli obblighi con documentazione idonea. Le aziende fino a cinquanta lavoratori possono utilizzare le procedure standardizzate approvate con decreto interministeriale del trenta novembre duemiladodici, salvo alcune attività a rischio elevato. In un’ispezione si verifica non solo l’esistenza del documento, ma la sua coerenza con la realtà: macchine, mansioni e sostanze effettivamente presenti.",
