     "nar": "La sicurezza ha un costo, ma anche la non sicurezza costa: premi assicurativi, sanzioni, fermi, risarcimenti e danni d’immagine. L’INAIL prevede strumenti economici per incentivare chi investe nella prevenzione. Il primo è la riduzione del tasso medio di tariffa per prevenzione: le aziende che nell’anno precedente hanno effettuato interventi per il miglioramento delle condizioni di salute e sicurezza, ulteriori rispetto a quelli previsti dalla legge, possono presentare domanda entro il ventotto febbraio con il modulo dedicato, raggiungendo il punteggio minimo previsto e allegando la documentazione probatoria. Gli interventi ammessi comprendono, ad esempio, l’adozione di sistemi di gestione certificati, buone prassi validate, formazione aggiuntiva, sostituzione di attrezzature e misure per i rischi specifici. La riduzione è decrescente con la dimensione aziendale ed è quindi più vantaggiosa per le piccole imprese. Il secondo strumento sono i bandi ISI, che finanziano con contributi in conto capitale progetti di miglioramento dei livelli di salute e sicurezza, come la sostituzione di macchine obsolete, la riduzione del rischio da movimentazione manuale o la bonifica dell’amianto, secondo le percentuali e i massimali stabiliti in ciascun bando. Per chi decide, questi strumenti migliorano il ritorno economico degli investimenti in prevenzione.",
